#!/usr/bin/env python3
"""Offline campaign CLI; JSON stdin/stdout, diagnostics on stderr."""
import json
import math
from pathlib import Path
import sys
sys.path.insert(0, str(Path(__file__).resolve().parent / "src"))
from eywa.offline import execute

LIMIT = 64 * 1024 * 1024

def pairs(items):
    d = {}
    for key, value in items:
        if key in d: raise ValueError("duplicate key")
        d[key] = value
    return d

def bad(value): raise ValueError("nonfinite")
def finite(value):
    result = float(value)
    if not math.isfinite(result): raise ValueError("nonfinite")
    return result

def read_request():
    raw = sys.stdin.buffer.read(LIMIT + 1)
    if len(raw) > LIMIT: raise ValueError("input cap")
    return json.loads(raw.decode("utf-8"), object_pairs_hook=pairs,
                      parse_constant=bad, parse_float=finite)

def main():
    try:
        request = read_request()
    except (ValueError, UnicodeError, RecursionError, OSError):
        result = {"error": "INVALID_INPUT"}
    else:
        try:
            result = execute(request)
        except Exception:
            result = {"error": "INVALID_INPUT"}
    try:
        text = json.dumps(result, ensure_ascii=True, separators=(",", ":"),
                          allow_nan=False)
    except (TypeError, ValueError, RecursionError):
        text = '{"error":"INVALID_INPUT"}'
    sys.stdout.write(text)
    sys.stdout.write("\n")
    sys.stdout.flush()
if __name__ == "__main__": main()
PYEOF
